```st
FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR

VAR_OUTPUT
    motorUp   : BOOL := FALSE;
    motorDown : BOOL := FALSE;
    errorFlag : BOOL := FALSE;
END_VAR

VAR
    state         : INT := 0;  // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    prevOpenBtn   : BOOL := FALSE;
    prevCloseBtn  : BOOL := FALSE;
    obstacleSeen  : BOOL := FALSE;  // Latch: obstacle detected since last valid command
END_VAR

VAR
    openBtnRising  : BOOL;
    closeBtnRising : BOOL;
END_VAR

// Rising edge detection
openBtnRising  := openBtn AND NOT prevOpenBtn;
closeBtnRising := closeBtn AND NOT prevCloseBtn;

// Update button history for next scan
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

// State machine
CASE state OF
    0:  // IDLE
        motorUp   := FALSE;
        motorDown := FALSE;

        // Clear obstacle latch when valid command starts
        IF openBtnRising THEN
            obstacleSeen := FALSE;
        END_IF
        IF closeBtnRising THEN
            obstacleSeen := FALSE;
        END_IF

        // Transitions: only if no obstacle seen since last valid command
        IF openBtnRising AND NOT openLimit AND NOT obstacleSeen THEN
            state := 1;  // -> OPENING
        ELSIF closeBtnRising AND NOT closeLimit AND NOT obstacleSeen THEN
            state := 2;  // -> CLOSING
        END_IF

    1:  // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;

        // Latch obstacle detection
        IF obstacle THEN
            obstacleSeen := TRUE;
        END_IF

        // Check for openLimit OR obstacle
        IF openLimit THEN
            motorUp := FALSE;
            state := 0;  // -> IDLE
        ELSIF obstacle THEN
            motorUp := FALSE;
            errorFlag := TRUE;
            state := 3;  // -> FAULT
        END_IF

    2:  // CLOSING
        motorUp   := FALSE;
        motorDown := TRUE;

        // Check for obstacle
        IF obstacle THEN
            motorDown := FALSE;
            state := 1;  // -> OPENING (reverse)
        ELSIF closeLimit THEN
            motorDown := FALSE;
            state := 0;  // -> IDLE
        END_IF

    3:  // FAULT
        motorUp   := FALSE;
        motorDown := FALSE;
        // errorFlag remains latched

        // Manual reset: both buttons pressed simultaneously
        IF openBtnRising AND closeBtnRising THEN
            obstacleSeen := FALSE;
            errorFlag := FALSE;
            state := 0;  // -> IDLE
        END_IF
END_CASE
END_FUNCTION_BLOCK
```

